// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // The fuzzed parameters: an address 'from', an address 'callee' (we'll supply a helper's address),
    // an array of addresses 'tos' and a value 'v'. We cannot fuzz the helper contract's code, so
    // we deploy an adversarial helper that implements transfer(address,address,uint256) and
    // sometimes returns false while transferFrom would return true; the fuzzer still controls 'from',
    // 'v', and the contents/length of 'tos'.
    function testFuzz_property(address from, uint256 v, address[] memory tos) public {
        // Keep domain wide but require a non-empty tos to satisfy require(_tos.length > 0) in C.
        vm.assume(tos.length > 0);

        // Deploy an adversarial callee that implements transfer(address,address,uint256)
        // and will return false (i.e., a boolean false without reverting) for some inputs,
        // while the correct selector transferFrom(...) would succeed. This models an external
        // counterparty whose transfer selector semantics differ from transferFrom.
        AdversarialCallee adv = new AdversarialCallee();

        // Call through c.transfer; we must capture whether it returns (ok==true) or reverts (ok==false).
        bool ok;
        try c.transfer(from, address(adv), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE ASSERTION: The reference implementation always returns true (i.e., call completes)
        // for any admissible inputs (non-empty tos). The mutant that changes the selector may hit the
        // adversarial callee's transfer(...) which returns false causing the call to fail (require(_s) fails),
        // so for some inputs the mutant will make ok == false while the reference keeps ok == true.
        // We therefore assert that the reference call completed (ok == true) for the tested inputs.
        assertTrue(ok);
    }
}

// Minimal adversarial helper: Implements transfer(address,address,uint256) and returns false
// (without reverting). This simulates a contract whose transfer selector behaves differently
// from transferFrom and can cause the mutated contract to fail the internal require on the
// low-level call's success boolean.
contract AdversarialCallee {
    // Example transfer selector: returns boolean false to break the mutant's expectation
    function transfer(address, address, uint256) external pure returns (bool) {
        return false;
    }

    // Also implement transferFrom to behave correctly (return true) so the reference works
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz params: from address, uint256 value, and an array of recipient addresses
    function testFuzz_property(address from, uint256 v, address[] memory _tos) public {
        // Keep domain wide but ensure _tos is non-empty as required by the contract
        vm.assume(_tos.length > 0);

        // Deploy an adversarial helper that will expose the difference between selectors.
        // The helper implements transfer(address,address,uint256) which REVERTS to simulate
        // a callee behavior that causes the mutant (which calls transfer(...)) to fail,
        // while the reference calls transferFrom(...) and will not hit this reverting function.
        AdversarialReverter adv = new AdversarialReverter();

        // Call through c.transfer. We cannot rely on a raw fuzzed address as callee because EOAs always succeed.
        // Pass adv address as caddress so the low-level call inside C reaches the adversarial contract.
        bool ok;
        try c.transfer(from, address(adv), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE / ASSERTION: On the reference implementation, for every admissible input (here any from, v and non-empty _tos),
        // c.transfer(...) always completes successfully (does not revert) and thus ok == true.
        // The mutant that calls transfer(...) selector may hit AdversarialReverter and cause the call to revert for some inputs,
        // making ok == false; therefore this assertion distinguishes the mutant.
        assertTrue(ok);
    }
}

// Adversarial helper: provides a transfer(address,address,uint256) function that ALWAYS reverts.
// This simulates an external contract whose transfer selector causes the mutant to fail, while the
// reference calling transferFrom(...) would not invoke this function.
contract AdversarialReverter {
    // Matches the selector transfer(address,address,uint256)
    function transfer(address, address, uint256) external pure {
        revert("adversarial revert");
    }
}

